/* keyframe name | duration | easing-function | delay |
iteration-count | direction | fill-mode | play-state | name */
p {
    animation: wiggle 10s ease-in-out infinite;
}

@keyframes wiggle {
    0% {
        margin-left: 4em;
    }
    50% {
        margin-left: 12em;
    }
    100% {
        margin-left: 4em;
    }
}

css
/* change button color to blue with white text on hover */
button:hover {
  background-color: blue;
  color: white;
}

/* change button color to darkblue when the button is active (clicked) */
button:active {
  background-color: darkblue;
}

/* change input color to green when the input is in focus (clicked) */
input:focus {
  border-color: green;
}

/* change link text color to blue when the link was already visited */
a:visited {
  color: blue;
}

/* make first list item element bold */
ul li:first-child {
  font-weight: bold;
}

/* make last list item element bold */
ul li:last-child {
  font-weight: bold;
}

/* give every second item a lightgrey background */
ul li:nth-child(2n) { 
  background-color: lightgray;
}

/* give the third item a lightgrey background */
ul li:nth-child(3) {
  font-style: italic;
}

/* give a checkbox a green outline when it's checked */
input[type="checkbox"]:checked {
  outline: 2px solid green;
}

css
a {
  font-variation-settings: "wght" 250, "ital" 0;
  transition: font-variation-settings letter-spacing .3s ease;
}

/* when hovered: the italic value increases */
a:hover {
  font-variation-settings: "wght" 250, "ital" 12;
  transition: font-variation-settings letter-spacing .3s ease;
}

