css
/* Desktop Size and Light Mode*/
body{
  font-size: 16px;
  background-color: white;
  color: black;
}
/* Tablet Size */
@media (max-width: 900px) {
  body{
      font-size: 14px;
  }
}
/* Mobile Size */
@media (max-width: 400px) {
  body{
      font-size: 12px;
  }
}
/* when dark mode is active */ 
@media (prefers-color-scheme: dark) {
  body{
    background-color: black;
    color: white;
  }
}

